	@Test
	void buffersIntegrityHashUpdatesForPrimitiveRecords() throws Exception {
		ByteBuffer expected = ByteBuffer.allocate(1024 * (Integer.BYTES + Long.BYTES));
		for (int value = 0; value < 1024; value++) {
			expected.putInt(value).putLong(value + 1L);
		}
		MessageDigest expectedDigest = BulkArtifactIntegrity.newDigest();
		expectedDigest.update(expected.array());
		String expectedHash = BulkArtifactIntegrity.finish(expectedDigest);
		for (BulkCodec codec : List.of(BulkCodec.NONE, BulkCodec.FAST)) {
			Path path = temporaryDirectory.resolve("buffered-integrity-" + codec.token());
			CountingMessageDigest digest = new CountingMessageDigest();
			try (DataOutputStream output = BulkLz4.output(path, codec, null, digest)) {
				for (int value = 0; value < 1024; value++) {
					output.writeInt(value);
					output.writeLong(value + 1L);
				}
			}
			assertThat(BulkArtifactIntegrity.finish(digest)).isEqualTo(expectedHash);
			assertThat(digest.singleByteUpdates).as("hashing uses the admitted stream buffer").isZero();
			assertThat(digest.chunkUpdates).isLessThanOrEqualTo((expected.capacity() + 8191) / 8192);
		}
	}

	@Test
	void trackedOutputForwardsBothArrayWriteOverloads() throws Exception {
		byte[] values = { 1, 2, 3, 4, 5, 6 };
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		expected.write(values);
		expected.write(values, 1, 4);
		CountingOutputStream outputDelegate = new CountingOutputStream();

		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 64, 1);
				BulkTaskScheduler.ResourceScope resources = scheduler.reserveStreamResources(0, 1)) {
			BulkTaskScheduler.OpenFileHandle handle = scheduler.trackOpenFileHandle();
			resources.trackHandle(handle);
			try (BulkLz4.TrackedOutputStream output = new BulkLz4.TrackedOutputStream(outputDelegate, handle,
					resources)) {
				output.write(values);
				output.write(values, 1, 4);
			}
		}

		assertThat(outputDelegate.bytes.toByteArray()).containsExactly(expected.toByteArray());
		assertThat(outputDelegate.singleByteWrites).as("tracked writes should preserve array batching").isZero();
		assertThat(outputDelegate.arrayWriteCalls).as("one delegate array write per caller array write").isEqualTo(2);
	}

	@Test
	void integrityReadsRemainForwardOnlyAndVerifySkippedBytes() throws Exception {
		byte[] bytes = new byte[3 * BulkLz4.STREAM_BUFFER_BYTES + 17];
		for (int index = 0; index < bytes.length; index++) {
			bytes[index] = (byte) (index * 31);
		}
		Path path = temporaryDirectory.resolve("forward-only.bin");
		Files.write(path, bytes);
		MessageDigest digest = BulkArtifactIntegrity.newDigest();
		digest.update(bytes);
		String expectedDigest = BulkArtifactIntegrity.finish(digest);
		try (DataInputStream input = BulkArtifactIntegrity.input(BulkLz4.input(path, BulkCodec.NONE), path,
				expectedDigest)) {
			assertThat(input.markSupported()).isFalse();
			input.mark(Integer.MAX_VALUE);
			assertThatThrownBy(input::reset).isInstanceOf(IOException.class);
			assertThat(input.skip(7)).isEqualTo(7L);
			assertThat(input.readUnsignedByte()).isEqualTo(Byte.toUnsignedInt(bytes[7]));
			input.skipNBytes(bytes.length - 8L);
			assertThat(input.read()).isEqualTo(-1);
			assertThat(input.read()).isEqualTo(-1);
		}
		try (DataInputStream input = BulkArtifactIntegrity.input(BulkLz4.input(path, BulkCodec.NONE), path,
				"0".repeat(64))) {
			assertThatThrownBy(input::readAllBytes).isInstanceOf(IOException.class).hasMessageContaining("integrity");
			assertThatThrownBy(input::read).isInstanceOf(IOException.class).hasMessageContaining("integrity");
		}
	}

	@Test
	void resumeRejectsSameLengthReferenceCountCorruption() throws Exception {
		Path target = temporaryDirectory.resolve("store");
		AtomicBoolean nativeRunsComplete = new AtomicBoolean();
		LmdbStoreConfig config = new LmdbStoreConfig();
		LmdbBulkLoader interrupted = LmdbBulkLoader.builder(target, config)
				.compression(BulkCompression.NONE)
				.progressListener(snapshot -> {
					if (snapshot.phase() == BulkLoadPhase.BUILD_NATIVE_RUNS && snapshot.phaseComplete()) {
						nativeRunsComplete.set(true);
					}
				})
				.cancellationSignal(nativeRunsComplete::get)
				.build();
		assertThatThrownBy(() -> interrupted.load(new ByteArrayInputStream(
				"<urn:subject> <urn:predicate> <urn:object> .\n".getBytes(StandardCharsets.UTF_8)),
				"urn:input:", RDFFormat.NTRIPLES))
						.isInstanceOf(CancellationException.class);
		Path referenceCounts = BulkLoadWorkspace.controlDirectory(target).resolve("value-ref-count-records.bin");
		byte[] bytes = Files.readAllBytes(referenceCounts);
		ByteBuffer header = ByteBuffer.wrap(bytes);
		int keyLength = header.getInt();
		int valueLength = header.getInt();
		assertThat(keyLength).isPositive();
		assertThat(valueLength).isPositive();
		int countByte = 2 * Integer.BYTES + keyLength + valueLength - 1;
		bytes[countByte]++;
		Files.write(referenceCounts, bytes);
		assertThat(Files.size(referenceCounts)).isEqualTo(bytes.length);

		assertThatThrownBy(() -> LmdbBulkLoader.builder(target, config).build().resume())
				.as("resuming must verify the native records before certifying prepared reference counts")
				.isInstanceOf(IOException.class)
				.hasMessageContaining("integrity");
		assertThat(target).doesNotExist();
	}

	@Test
	void byteRecordDigestsCoverEmptySingleAndMergedRunsForBothCodecs() throws Exception {
		for (BulkCodec codec : List.of(BulkCodec.NONE, BulkCodec.FAST)) {
			for (int count : List.of(0, 1, 200)) {
				Path output = temporaryDirectory.resolve("bytes-" + codec.token() + "-" + count + ".bin");
				try (ExternalByteKeySorter sorter = new ExternalByteKeySorter(temporaryDirectory, "bytes", 64L, 3,
						codec)) {
					for (int value = count - 1; value >= 0; value--) {
						sorter.add(ByteBuffer.allocate(Integer.BYTES).putInt(value).array(), new byte[] { 1 });
					}
					ExternalByteKeySorter.SortedRecordFile sorted = sorter.finish(output);
					assertThat(sorted.contentDigest()).matches("[0-9a-f]{64}");
					int[] actual = { 0 };
					sorted.forEach((key, value) -> actual[0]++);
					assertThat(actual[0]).isEqualTo(count);
					if (codec == BulkCodec.NONE && count > 0) {
						byte[] bytes = Files.readAllBytes(output);
						bytes[bytes.length - 1]++;
						Files.write(output, bytes);
						assertThatThrownBy(() -> sorted.forEach((key, value) -> {
						})).isInstanceOf(IOException.class).hasMessageContaining("integrity");
					}
				}
			}
		}
	}

