	@Test
	void resumeRejectsSameLengthResolvedDependencyCorruption() throws Exception {
		Path target = temporaryDirectory.resolve("store");
		LmdbStoreConfig config = new LmdbStoreConfig();
		interruptAfterResolution(target, config);
		Path dependencies = BulkLoadWorkspace.controlDirectory(target).resolve("resolved-value-components.bin");
		byte[] bytes = Files.readAllBytes(dependencies);
		ByteBuffer tuples = ByteBuffer.wrap(bytes);
		long firstNamespace = tuples.getLong(2 * Long.BYTES);
		boolean replaced = false;
		for (int offset = 3 * Long.BYTES; offset < bytes.length; offset += 3 * Long.BYTES) {
			long namespace = tuples.getLong(offset + 2 * Long.BYTES);
			if (namespace != firstNamespace) {
				tuples.putLong(2 * Long.BYTES, namespace);
				replaced = true;
				break;
			}
		}
		assertThat(replaced).as("the fixture contains two valid, distinct namespace IDs").isTrue();
		Files.write(dependencies, bytes);

		assertThatThrownBy(() -> LmdbBulkLoader.builder(target, config).build().resume())
				.as("a changed namespace dependency must not become a newly trusted native dictionary")
				.isInstanceOf(IOException.class)
				.hasMessageContaining("integrity");
		assertThat(target).doesNotExist();
	}

