	private static void interruptAfterResolution(Path target, LmdbStoreConfig config) {
		AtomicBoolean resolved = new AtomicBoolean();
		LmdbBulkLoader interrupted = LmdbBulkLoader.builder(target, config)
				.compression(BulkCompression.NONE)
				.progressListener(snapshot -> {
					if (snapshot.phase() == BulkLoadPhase.RESOLVE_IDS && snapshot.phaseComplete()) {
						resolved.set(true);
					}
				})
				.cancellationSignal(resolved::get)
				.build();
		assertThatThrownBy(() -> interrupted.load(new ByteArrayInputStream(
				"<urn:first:subject> <urn:other:predicate> <urn:first:object> .\n"
						.getBytes(StandardCharsets.UTF_8)),
				"urn:input:", RDFFormat.NTRIPLES))
						.isInstanceOf(CancellationException.class);
	}

	private static final class CountingMessageDigest extends MessageDigest {
		private final MessageDigest delegate;
		private long singleByteUpdates;
		private long chunkUpdates;

		private CountingMessageDigest() throws NoSuchAlgorithmException {
			super("SHA-256");
			delegate = MessageDigest.getInstance("SHA-256");
		}

		@Override
		protected void engineUpdate(byte value) {
			singleByteUpdates++;
			delegate.update(value);
		}

		@Override
		protected void engineUpdate(byte[] bytes, int offset, int length) {
			chunkUpdates++;
			delegate.update(bytes, offset, length);
		}

		@Override
		protected byte[] engineDigest() {
			return delegate.digest();
		}

		@Override
		protected void engineReset() {
			delegate.reset();
		}
	}

	private static final class CountingOutputStream extends OutputStream {
		private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		private int singleByteWrites;
		private int arrayWriteCalls;

		@Override
		public void write(int value) {
			singleByteWrites++;
			bytes.write(value);
		}

		@Override
		public void write(byte[] values, int offset, int length) {
			arrayWriteCalls++;
			bytes.write(values, offset, length);
		}
	}
